UPDATE daily_entry_template
SET product_id = #{p.targetId}, display_name = #{p.targetName},
    normalized_name = #{p.targetNormalized}, product_name_snapshot = #{p.targetName},
    updated_at = #{p.now}
WHERE id = #{p.templateId}


UPDATE product
SET status = 'MERGED', merged_into_id = #{p.targetId}, updated_at = #{p.now}
WHERE id = #{p.sourceId} AND status <> 'MERGED'


UPDATE daily_entry_template
SET display_name = #{p.displayName}, normalized_name = #{p.normalizedName},
    product_name_snapshot = #{p.displayName}, updated_at = #{p.now}
WHERE entry_type = 'EXPENSE' AND product_id = #{p.productId}
